'use strict';
const PROCUREMENT_UI5={bind,help,financeView,roastersView,supplyView,performanceView,performanceDetail5};
TITLES.procurement='Dodavatelé, nákup zrn & závazky';
function procurementView(){const p=state.procurement5,payables=p.payables.filter(x=>x.paid===null),active=p.orders.filter(o=>o.received===null);return `<p class="intro">Porovnej čtyři fiktivní dodavatele podle ceny, kvality, termínu a kapacity. Objednaná zrna vstoupí do výroby až po skutečném doručení. Běžný nákup a expres pražíren zůstávají dostupné v dosavadní správě zásob.</p><div class="report-overview5">${metric('NA CESTĚ',number(active.reduce((n,o)=>n+o.kg,0),1)+' kg',active.length+' zásilek')}${metric('NEUHRAZENÉ FAKTURY',money(procurementPayable5()),payables.filter(x=>x.due<=state.week).length+' splatných')}${metric('ÚVĚR VČETNĚ ZÁSILEK',money(procurementCredit5()),'Limit 300 000 Kč')}${metric('PRAVIDELNÉ ODBĚRY',p.contracts.filter(c=>c.status==='active').length,'Smlouvy se zapnutým objednáváním')}</div><div class="cards">${Object.entries(SUPPLIERS5).map(([id,s])=>`<section class="card"><h2>${esc(s.name)}</h2><p class="sub">${esc(s.description)}</p>${rows([['Cena zrn',number(s.price*100)+' % trhu + '+money(s.freight)+'/kg dopravy'],['Odchylka kvality', (s.quality>=0?'+':'')+s.quality+' bodů, partie ±2'],['Běžná doprava',s.lead+' týdnů'],['Modelová spolehlivost',s.reliability+' % bez zpoždění'],['Množství objednávky',s.min+'–'+s.max+' kg'],['Volná kapacita týdne',procurementCapacity5(id)+' / '+s.capacity+' kg']])}<div class="actions"><button class="primary" data-procurement-new5="${id}" data-kind="order" ${state.over?'disabled':''}>Objednat zrna</button><button class="soft" data-procurement-new5="${id}" data-kind="contract" ${state.over?'disabled':''}>Pravidelný odběr</button></div></section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>Objednávky na cestě</h2>${active.length?`<div class="table-scroll"><table class="data"><thead><tr><th>Dodavatel / původ</th><th>Množství</th><th>Hodnota</th><th>Původní / nynější termín</th><th>Platba / stav</th></tr></thead><tbody>${active.map(o=>`<tr><td>${esc(SUPPLIERS5[o.supplier].name)}<small>${esc(ORIGINS[o.origin].name)}</small></td><td>${o.kg} kg</td><td>${money(o.cost)}</td><td>T${o.expected} / T${o.due}</td><td>${o.terms?'Dva týdny po doručení':'Zaplaceno předem'}<small>${o.status==='delayed'?'Zpožděná zásilka':'Na cestě'}</small></td></tr>`).join('')}</tbody></table></div>`:empty('Žádná dodavatelská objednávka na cestě.')}<p class="sub">Zpoždění může přidat jeden či dva týdny. Partie zůstává zaplacenou zásilkou nebo budoucím závazkem; nedorazí podruhé.</p></section><section class="card" style="margin-top:24px"><h2>Pravidelné odběry s pevnou cenou</h2>${p.contracts.length?`<div class="table-scroll"><table class="data"><thead><tr><th>Dodavatel / původ</th><th>Odběr týdně</th><th>Pevná cena</th><th>Období</th><th>Poslední krok</th><th>Řízení</th></tr></thead><tbody>${p.contracts.map(c=>`<tr><td>${esc(SUPPLIERS5[c.supplier].name)}<small>${esc(ORIGINS[c.origin].name)}</small></td><td>${c.kg} kg</td><td>${money(c.unit)}/kg</td><td>T${c.start}–${c.end-1}<small>${({active:'Aktivní',paused:'Pozastavený',expired:'Ukončené období',cancelled:'Zrušený'})[c.status]}</small></td><td>${esc(c.last?.text||'Čeká na první tah')}</td><td>${['active','paused'].includes(c.status)&&state.week<c.end?`<button class="soft mini" data-procurement-status5="${c.id}" data-status="${c.status==='active'?'paused':'active'}">${c.status==='active'?'Pozastavit':'Obnovit'}</button><button class="quiet mini" data-procurement-status5="${c.id}" data-status="cancelled">Ukončit</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Žádný pravidelný odběr.')}<p class="sub">12 nebo 26 kalendářních týdnů, sleva 8 % z ceny zrn dodavatele, doprava bez slevy. Sjednání stojí 2 500 Kč. Automatická objednávka hlídá kapacitu, rezervu a splatné faktury. Pozastavení ani nedostatek rezervy neprodlouží období; přijaté zásilky a faktury pokračují po ukončení.</p></section><section class="card" style="margin-top:24px"><h2>Faktury dodavatelů</h2>${p.payables.length?`<div class="table-scroll"><table class="data"><thead><tr><th>Dodavatel</th><th>Částka</th><th>Doručení</th><th>Splatnost</th><th>Stav</th></tr></thead><tbody>${p.payables.slice(-30).map(x=>`<tr><td>${esc(SUPPLIERS5[x.supplier].name)}</td><td>${money(x.amount)}</td><td>T${x.received}</td><td>T${x.due}</td><td class="${x.paid===null&&x.due<=state.week?'bad':''}">${x.paid!==null?'Uhrazeno T'+x.paid:x.due<=state.week?'Čeká na úhradu':'Před splatností'}</td></tr>`).join('')}</tbody></table></div>`:empty('Žádná faktura na splatnost.')}<p class="sub">Splatnost vyžaduje kavárnu a pracovníka Financí. Faktura vznikne při doručení, úhrada probíhá na začátku týdne splatnosti, pokud je dost hotovosti. Neuhrazená splatná faktura blokuje další úvěr daného dodavatele. Bez penále; další úhrada se zkusí v příštím tahu.</p></section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Dodavatelský report</h2><button class="soft" id="procurementReport5">Otevřít report firmy</button></div>${p.events.slice(-12).reverse().map(e=>`<p class="sub"><strong>T${e.week} · ${esc(SUPPLIERS5[e.supplier].name)}</strong><br>${esc(e.text)}${e.amount?' · '+money(e.amount):''}</p>`).join('')||empty('Zatím bez dodavatelských výsledků.')}<p class="sub">Nákup zrn vytváří zásobu, nikoli okamžitý provozní výdaj. Její náklad vstoupí do pražené kávy a později do prodané spotřeby. Platba faktury znovu nevytváří náklad.</p></section>`;}
function procurementDialog5(supplier,kind='order'){show(`<span class="eyelabel">NÁKUP ZELENÉ KÁVY</span><h2>${kind==='contract'?'Pravidelný odběr':'Dodavatelská objednávka'}</h2><div class="fields">${field('Dodavatel',`<select id="procSupplier5">${Object.entries(SUPPLIERS5).map(([id,s])=>option(id,s.name,supplier)).join('')}</select>`)}${field('Původ',`<select id="procOrigin5">${Object.entries(ORIGINS).map(([id,o])=>option(id,o.name,'brazil')).join('')}</select>`)}${field('Množství / objednávka',`<input id="procKg5" type="number" value="${Math.max(20,SUPPLIERS5[supplier].min)}">`)}${field('Platba',`<select id="procTerms5">${option(0,'Předem',0)}${option(2,'Dva týdny po doručení',0)}</select>`)}${field('Rezerva / týdny fixních nákladů',`<input id="procReserve5" type="number" min="1" max="8" value="2">`)}${kind==='contract'?field('Kalendářní období',`<select id="procWeeks5">${option(12,'12 týdnů',12)}${option(26,'26 týdnů',12)}</select>`):''}</div><div id="procQuote5"></div><div class="actions"><button class="soft" data-procurement-preview5="4">Výhled 4 týdnů</button><button class="soft" data-procurement-preview5="8">Výhled 8 týdnů</button><button class="primary" id="procCommit5">${kind==='contract'?'Sjednat odběr':'Objednat'}</button></div><div id="procComparison5"></div>`);let quoted=null;const read=()=>({supplier:el('procSupplier5').value,origin:el('procOrigin5').value,kg:Number(el('procKg5').value),terms:Number(el('procTerms5').value),reserve:Number(el('procReserve5').value),...(kind==='contract'?{weeks:Number(el('procWeeks5').value)}:{})}),refresh=()=>{quoted=null;el('procQuote5').innerHTML='';el('procComparison5').innerHTML='';try{const s=SUPPLIERS5[el('procSupplier5').value];el('procKg5').min=s.min;el('procKg5').max=s.max;quoted=procurementQuote5(read(),kind==='contract');el('procQuote5').innerHTML=rows([['Zrna a doprava',money(quoted.unit)+'/kg'],['Hodnota objednávky',money(quoted.cost)],['Kvalita partie',quoted.qualityLow+'–'+quoted.qualityHigh+' / 100'],['Očekávaný příjezd', 'Týden '+quoted.due],['Spolehlivost termínu',quoted.reliability+' %'],['Poplatek za odběr',money(quoted.fee)],['Platba teď',money(kind==='contract'?quoted.fee:quoted.terms?0:quoted.cost)],['Pevná cena odběru',kind==='contract'?quoted.weeks+' týdnů':'Jednorázový nákup']]);el('procComparison5').innerHTML='';procurementGuard5(quoted);el('procCommit5').disabled=state.over;}catch(e){el('procQuote5').innerHTML+=(quoted?'<p class="bad">'+esc(e.message)+'</p>':esc(e.message));el('procCommit5').disabled=true;}};for(const id of ['procSupplier5','procOrigin5','procKg5','procTerms5','procReserve5','procWeeks5'])if(el(id))el(id).onchange=refresh;refresh();
 on('[data-procurement-preview5]',b=>{try{const f=previewProcurement5({kind,data:read()},Number(b.dataset.procurementPreview5)),a=f.baseline.series,z=f.changed.series,sum=(s,k)=>s.reduce((n,h)=>n+h[k],0);el('procComparison5').innerHTML=`<h3>Výhled se změnou a bez ní</h3><div class="table-scroll"><table class="data"><thead><tr><th>Výsledek</th><th>Bez změny</th><th>Po změně</th></tr></thead><tbody>${[['Výsledek celé firmy',money(sum(a,'profit')),money(sum(z,'profit'))],['Hotovost na konci',money(a.at(-1)?.cash??state.cash),money(z.at(-1)?.cash??state.cash)],['Dodavatelé doručili',number(sum(a,'received'),1)+' kg',number(sum(z,'received'),1)+' kg'],['Hosté bez kávy',number(sum(a,'lost')),number(sum(z,'lost'))],['Neuhrazené faktury na konci',money(a.at(-1)?.payables??0),money(z.at(-1)?.payables??0)]].map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')}</tbody></table></div><p class="sub">Obě kopie odehrály skutečnou firmu včetně modelových zpoždění, výroby a plateb. Rozehraná hra zůstává v T${state.week}. ${f.baseline.over||f.changed.over?'Jedna varianta ukončila činnost před koncem období.':''}</p>`;}catch(e){toast(e.message)}});
 el('procCommit5').onclick=()=>{try{const data=read(),q=procurementQuote5(data,kind==='contract');procurementGuard5(q);confirmAction(kind==='contract'?'Sjednat pravidelný odběr?':'Objednat zrna?',esc(SUPPLIERS5[q.supplier].name)+' · '+q.kg+' kg · '+money(q.unit)+'/kg. '+(kind==='contract'?'Poplatek '+money(q.fee)+', automatické objednávky po '+q.weeks+' týdnů.':q.terms?'Faktura '+money(q.cost)+' bude splatná dva týdny po skutečném doručení.':'Platba '+money(q.cost)+' předem. Termín T'+q.due+' může ovlivnit zpoždění.'),()=>kind==='contract'?signProcurement5(data,q):buyProcurement5(data,q),kind==='contract'?'Sjednat':'Objednat')}catch(e){toast(e.message)}};}
financeView=function(){return `<section class="card" style="margin-bottom:24px"><h2>Závazky za zelenou kávu</h2>${rows([['Neuhrazené dodavatelské faktury',money(procurementPayable5())],['Úvěr včetně objednávek na cestě',money(procurementCredit5())]])}<button class="soft" data-goto="procurement">Otevřít dodavatele a splatnosti</button><p class="sub">Dodavatelské závazky jsou oddělené od bankovního dluhu a snižují hodnotu firmy. Úhrada mění hotovost; náklad zrn se účtuje při skutečné spotřebě kávy.</p></section>`+PROCUREMENT_UI5.financeView();};
roastersView=function(){return '<div class="actions"><button class="soft" data-goto="procurement">Porovnat dodavatele a podmínky nákupu</button></div>'+PROCUREMENT_UI5.roastersView();};
supplyView=function(){return '<div class="actions"><button class="soft" data-goto="procurement">Dodavatelé, pravidelné odběry a splatnosti</button></div>'+PROCUREMENT_UI5.supplyView();};
performanceView=function(){const html=PROCUREMENT_UI5.performanceView();if(reportKind5!=='suppliers')return html;return html.replace('Soupeři mají vlastní ceny a baristy. Pobočky platí kávu, mzdy, nájem a provoz; skutečné obsloužené návštěvy omezí kapacita. Výsledek firmy navíc zahrnuje obchod, centrálu a úroky; investice snižují hotovost zvlášť. Jejich šarže a individuální fronty se nesimulují.','Dodavatelé ukazují skutečné objednávky, doručení, platby a faktury. Platba zrn není okamžitá ztráta; zrna vstupují do nákladu prodané kávy. Kvalita a včasnost jsou průměry zaznamenaných týdnů s doručením.');};
performanceDetail5=function(id){PROCUREMENT_UI5.performanceDetail5(id);if(reportKind5==='suppliers'&&el('reportManage5'))el('reportManage5').onclick=()=>{el('modal').close();goto('procurement')};};
bind=function(){PROCUREMENT_UI5.bind();on('[data-procurement-new5]',b=>procurementDialog5(b.dataset.procurementNew5,b.dataset.kind));on('[data-procurement-status5]',b=>{const id=b.dataset.procurementStatus5,status=b.dataset.status;if(status==='cancelled')confirmAction('Ukončit pravidelný odběr?','Další objednávky se zastaví. Objednané zásilky a faktury pokračují; podpisový poplatek se nevrací.',()=>setProcurementStatus5(id,status),'Ukončit');else act(()=>setProcurementStatus5(id,status),'Pravidlo odběru uloženo.')});if(el('procurementReport5'))el('procurementReport5').onclick=()=>{reportKind5='suppliers';goto('performance')};};
help=function(){PROCUREMENT_UI5.help();const p=document.createElement('p');p.textContent='Edice 05.12: Dodavatelé & nákup zrn porovnává cenu, skutečnou kvalitu partií, termín a kapacitu. Nákup předem vstoupí do zásoby až po příjezdu. Splatnost dva týdny po doručení vyžaduje Finance a má celkový limit 300 000 Kč včetně zásilek. Rámcový odběr drží cenu na 12/26 kalendářních týdnů, poplatek 2 500 Kč a slevu 8 % z ceny zrn. Lze ho pozastavit či ukončit; objednané zásilky a faktury pokračují. Výhled 4/8 týdnů simuluje kopii firmy. Report ukazuje skutečné dodávky a platby; platba faktury není druhý náklad.';el('modalContent').append(p)};el('help').onclick=help;render();
